using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;
public static class ReuploadGroveMeshes {
 public static string Main(){int count=0;AssetDatabase.StartAssetEditing();try{foreach(var guid in AssetDatabase.FindAssets("t:Mesh",new[]{"Assets/NewMap/FiveHangars/HillTrees"})){var p=AssetDatabase.GUIDToAssetPath(guid);var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(p);var vertices=mesh.vertices;var normals=mesh.normals;var uv=mesh.uv;var tangents=mesh.tangents;var tris=Enumerable.Range(0,mesh.subMeshCount).Select(i=>mesh.GetTriangles(i)).ToArray();mesh.Clear();mesh.indexFormat=IndexFormat.UInt32;mesh.vertices=vertices;if(normals.Length==vertices.Length)mesh.normals=normals;if(uv.Length==vertices.Length)mesh.uv=uv;if(tangents.Length==vertices.Length)mesh.tangents=tangents;mesh.subMeshCount=tris.Length;for(int i=0;i<tris.Length;i++)mesh.SetTriangles(tris[i],i);mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);count++;}}finally{AssetDatabase.StopAssetEditing();}AssetDatabase.SaveAssets();return "Rebuilt and uploaded native vertex/index buffers for "+count+" grove meshes";}
}
